#include <iostream>
struct N { int v; N* l; N* r; };
N* insert(N* t, int x) {
    if (!t) return new N{x, 0, 0};
    if (x < t->v) t->l = insert(t->l, x); else t->r = insert(t->r, x);
    return t;
}
int main() {
    N* root = 0;
    for (int x : {8, 3, 10, 1}) root = insert(root, x);
    std::cout << root->l->l->v;
}

